const socialIconMap: Record<SocialIconKey, ComponentType<IconProps>> = {
  github: IconGithub,
  linkedin: IconLinkedin,
  instagram: IconInstagram,
  x: IconX,
  youtube: IconYoutube,
  aws: IconAws,
  mail: IconMail,
};

export function SocialIcon({
  name,
  ...props
}: IconProps & { name: SocialIconKey }) {
  const Component = socialIconMap[name];
  return <Component {...props} />;
}

